            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = in.read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int stations = fs.nextInt();
        int railCount = fs.nextInt();

        @SuppressWarnings("unchecked")
        ArrayList<Edge>[] graph = new ArrayList[stations];
        for (int i = 0; i < stations; i++) graph[i] = new ArrayList<>();

        int[] edgeU = new int[railCount];
        int[] edgeV = new int[railCount];
        int[] edgeW = new int[railCount];

        for (int i = 0; i < railCount; i++) {
