            edgeU[i] = a;
            edgeV[i] = b;
            edgeW[i] = w;
            graph[a].add(new Edge(b, i, w));
            graph[b].add(new Edge(a, i, w));
        }

        boolean[] bridge = new boolean[railCount];
        int[] discovery = new int[stations];
        int[] low = new int[stations];
        int[] parent = new int[stations];
        int[] parentEdge = new int[stations];
        int[] nextEdge = new int[stations];
        int[] stack = new int[stations];
        Arrays.fill(parent, -1);
        Arrays.fill(parentEdge, -1);

