            if (discovery[root] != 0) continue;

            int top = 0;
            stack[0] = root;
            discovery[root] = low[root] = ++timer;

            while (top >= 0) {
                int u = stack[top];
                if (nextEdge[u] < graph[u].size()) {
                    Edge e = graph[u].get(nextEdge[u]++);
                    if (e.id == parentEdge[u]) continue;

