                        low[u] = Math.min(low[u], discovery[v]);
                    }
                } else {
                    top--;
                    int p = parent[u];
                    if (p != -1) {
                        low[p] = Math.min(low[p], low[u]);
                        if (low[u] > discovery[p]) {
                            bridge[parentEdge[u]] = true;
                        }
                    }
                }
            }
        }

        int[] cycleId = new int[stations];
        Arrays.fill(cycleId, -1);
        ArrayList<Integer> cycleLengths = new ArrayList<>();
        int[] queue = new int[stations];

        for (int start = 0; start < stations; start++) {
            if (cycleId[start] != -1) continue;

