            for (Edge e : graph[start]) {
                if (!bridge[e.id]) {
                    hasCycleEdge = true;
                    break;
                }
            }
            if (!hasCycleEdge) continue;

            int id = cycleLengths.size();
            int head = 0, tail = 0;
            queue[tail++] = start;
            cycleId[start] = id;

            while (head < tail) {
                int u = queue[head++];
                for (Edge e : graph[u]) {
                    if (!bridge[e.id] && cycleId[e.to] == -1) {
                        cycleId[e.to] = id;
                        queue[tail++] = e.to;
                    }
                }
            }

            cycleLengths.add(0);
        }

        for (int u = 0; u < stations; u++) {
            if (cycleId[u] == -1) continue;
            for (Edge e : graph[u]) {
                if (!bridge[e.id]) {
                    cycleLengths.set(cycleId[u], cycleLengths.get(cycleId[u]) + e.weight);
                }
            }
        }
        for (int i = 0; i < cycleLengths.size(); i++) {
            cycleLengths.set(i, cycleLengths.get(i) / 2);
        }

        int queries = fs.nextInt();
        StringBuilder output = new StringBuilder();

        for (int qi = 0; qi < queries; qi++) {
            int start = fs.nextInt() - 1;
            int trainLength = fs.nextInt();

            long[] distance = new long[stations];
            Arrays.fill(distance, Long.MAX_VALUE);
            PriorityQueue<State> pq = new PriorityQueue<>();

            for (int v = 0; v < stations; v++) {
                int id = cycleId[v];
                if (id != -1 && cycleLengths.get(id) >= trainLength) {
                    long initial = cycleLengths.get(id);
                    if (initial < distance[v]) {
                        distance[v] = initial;
                        pq.add(new State(v, initial));
                    }
                }
            }

            while (!pq.isEmpty()) {
                State current = pq.poll();
                if (current.distance != distance[current.node]) continue;

                for (Edge e : graph[current.node]) {
                    long candidate = current.distance + 2L * e.weight;
                    if (candidate < distance[e.to]) {
                        distance[e.to] = candidate;
                        pq.add(new State(e.to, candidate));
                    }
                }
            }

            output.append(distance[start] == Long.MAX_VALUE ? -1 : distance[start])
                  .append('\n');
        }

        System.out.print(output);
    }
